	protected ThirdParty read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created ThirdParty" );

		ThirdParty entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read ThirdParty with primary key" );
		msg.append( thirdPartyId );
		
		ThirdPartyFetchOneSummary fetchOneSummary = new ThirdPartyFetchOneSummary( thirdPartyId );

		try {
			entity = ThirdPartyService.getThirdPartyInstance().getThirdParty( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found ThirdParty " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a ThirdParty.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a ThirdParty." );

		StringBuilder msg = new StringBuilder( "Failed to update a ThirdParty : " );        
		ThirdParty entity = read();
		UpdateThirdPartyCommand command = generateUpdateCommand();
		command.setThirdPartyId(entity.getThirdPartyId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created ThirdParty." );

			// for use later on...
			thirdPartyId = entity.getThirdPartyId();

			ThirdPartyService proxy = ThirdPartyService.getThirdPartyInstance();  

			proxy.updateThirdParty( command ).get();

			LOGGER.info( "-- Successfully saved ThirdParty - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + thirdPartyId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a ThirdParty.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created ThirdParty." );

		ThirdParty entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read ThirdParty with id " + thirdPartyId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read ThirdParty with id " + thirdPartyId );

			throw e;
		}

		try{
			ThirdPartyService.getThirdPartyInstance().delete( new DeleteThirdPartyCommand( entity.getThirdPartyId() ) ).get();
			LOGGER.info( "-- Successfully deleted ThirdParty with id " + thirdPartyId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete ThirdParty with id " + thirdPartyId );

			throw e;
		}
	}

	/**
	 * get all ThirdPartys.
	 */
	protected List<ThirdParty> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of ThirdPartys:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all ThirdParty : " );        
		List<ThirdParty> collection  = new ArrayList<>();

		try {
			// call the static get method on the ThirdPartyService
			collection = ThirdPartyService.getThirdPartyInstance().getAllThirdParty();
			assertNotNull( collection, "An Empty collection of ThirdParty was incorrectly returned.");
			
			// Now print out the values
			ThirdParty entity = null;            
			Iterator<ThirdParty> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getThirdPartyId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

